        - entries[13] * entries[6] * entries[34]
        + entries[13] * entries[10] * entries[30]
        + entries[17] * entries[2] * entries[34]
        - entries[17] * entries[10] * entries[26]
        - entries[21] * entries[2] * entries[30]
        + entries[21] * entries[6] * entries[26]
        + entries[25] * entries[6] * entries[22]
        - entries[25] * entries[10] * entries[18]
        - entries[29] * entries[2] * entries[22]
        + entries[29] * entries[10] * entries[14]
